import { createLogHost, levelPlugin } from '@migaia/log-host'
import { batchFeature } from '@migaia/log-host/features'
import { filePlugin } from '@migaia/log-plugin-file'

// 示例 writer 只打印；不传 writer 时，Node/Bun/Deno 直接追加到真实文件
const writer = {
  async append(path: string, text: string) {
    const lines = text
      .trimEnd()
      .split('\n')
      .map((line) => JSON.parse(line).message)
    console.log(`追加到 ${path}：${lines.join('、')}`)
  },
  async rotate(path: string) {
    console.log(`轮转 ${path}`)
  }
}
const log = createLogHost({
  plugins: [
    levelPlugin(),
    filePlugin({
      path: 'app.ndjson',
      writer,
      rotate: { maxEntries: 2 }, // 一批达到 2 条后轮转
      features: { batch: batchFeature({ maxSize: 2 }) } // 每 2 条写一次
    })
  ]
})
log.info('a')
log.info('b')
log.info('c')
await log.shutdown('manual')

import { createLogHost, levelPlugin } from '@migaia/log-host'
import { batchFeature } from '@migaia/log-host/features'
import { filePlugin } from '@migaia/log-plugin-file'

/** 示例 writer 由应用拥有，插件卸载不会关闭它。 */
class MemoryWriter {
  /** 保留每次 append 的完整批次，便于应用转交实际存储。 */
  readonly writes: { path: string; text: string }[] = []
  /** append 的兑现表示本批内容已由 writer 接纳。 */
  async append(path: string, text: string): Promise<void> {
    this.writes.push({ path, text })
  }
}

/** 显式 writer 使同一配置可用于浏览器与服务端。 */
const writer = new MemoryWriter()
/** 输出级批量策略由 host 维护缓冲与排空。 */
const log = createLogHost({
  plugins: [
    levelPlugin(),
    filePlugin({
      path: 'application.ndjson',
      writer,
      features: { batch: batchFeature({ maxSize: 2 }) }
    })
  ]
})
log.info('first')
log.info('second')
await log.flush()
await log.shutdown('manual')

